void WriteOutgoingArguments(GuestMemory& memory, GuestAddress frame,
    const Spec& spec)
{
    constexpr std::uint64_t kFlags = 0x0408408400004000ull;
    const auto write_flags = [&]
    {
        memory.WriteU32(frame + 80u, static_cast<std::uint32_t>(kFlags >> 32));
        memory.WriteU32(frame + 84u, static_cast<std::uint32_t>(kFlags));
    };
    if (spec.store_order == StoreOrder::Word92First)
    {
        memory.WriteU32(frame + 92u, spec.outgoing92);
        write_flags();
        memory.WriteU32(frame + 108u, spec.outgoing108);
        memory.WriteU32(frame + 100u, spec.outgoing100);
    }
    else
    {
        memory.WriteU32(frame + 100u, spec.outgoing100);
        memory.WriteU32(frame + 92u, spec.outgoing92);
        memory.WriteU32(frame + 108u, spec.outgoing108);
        write_flags();
    }
}

