bool Apply(GuestAddress address, GuestMemory& memory,
    ManagerFacadeServices& manager_services,
    RegistrationServices& registration_services,
    std::uint64_t incoming_r3, GuestAddress caller_sp,
    std::uint64_t& result)
{
    const Spec* spec = std::lower_bound(std::begin(kSpecs), std::end(kSpecs),
        address, [](const Spec& entry, GuestAddress target)
        { return entry.address < target; });
    if (spec == std::end(kSpecs) || spec->address != address)
        return false;

    const GuestAddress frame = caller_sp -
        (spec->kind == Kind::ConstructorWithScratch ? 144u : 128u);
    if (spec->kind == Kind::LazySingleton)
    {
        const GuestAddress existing = memory.ReadU32(spec->singleton);
        if (existing != 0)
        {
            result = existing;
            return true;
        }
    }

    const std::uint64_t allocation = AllocateManagerBuffer(memory,
        manager_services, 376, frame);
    if (spec->kind == Kind::ConstructorWithScratch)
        memory.WriteU32(frame + 112u, static_cast<GuestAddress>(allocation));

    std::uint64_t constructed = 0;
    if (static_cast<GuestAddress>(allocation) != 0)
    {
        WriteOutgoingArguments(memory, frame, *spec);
        constructed = InitializeRegisteredObject(memory, RegisteredObjectInput{
            allocation, spec->object_size, spec->category, 0,
            spec->descriptor,
            spec->owner_is_incoming ? incoming_r3 : spec->owner,
            spec->tag, frame});
    }

    if (spec->kind == Kind::LazySingleton)
    {
        memory.WriteU32(spec->singleton, static_cast<GuestAddress>(constructed));
        (void)registration_services.Register(spec->callback, constructed, frame);
        result = memory.ReadU32(spec->singleton);
    }
    else
        result = constructed;
    return true;
}

